export function isShockPayload(raw: unknown): raw is ShockPayload {
  if (typeof raw !== 'object' || raw === null || Array.isArray(raw)) return false
  const record = raw as Record<string, unknown>
  const keys = Object.keys(record)
  if (keys.length !== PAYLOAD_KEYS.length) return false
  for (const key of PAYLOAD_KEYS) if (!keys.includes(key)) return false
  if (typeof record.intent !== 'string' || !INTENT_VALUES.includes(record.intent as ShockIntent)) return false
  if (typeof record.confidence !== 'string' || !CONFIDENCE_VALUES.includes(record.confidence as ShockConfidence)) return false
