function typedNoteFor(outcome: ParseRejected | ParseTimeout): string {
  if (outcome.status === 'timeout') return GEMINI_UNAVAILABLE_NOTE
  switch (outcome.reason) {
    case 'no_key':
      return 'Gemini key not configured, using preset cards'
    case 'rate_limited':
    case 'http_error':
    case 'network_error':
    case 'aborted':
      return GEMINI_UNAVAILABLE_NOTE
    case 'empty_input':
    case 'malformed_json':
    case 'bad_shape':
    case 'no_shock':
    case 'low_confidence':
    case 'all_neutral':
      return NO_SHOCK_NOTE
  }
}
