export function validateShockPayload(raw: unknown): ValidateOutcome {
  const problem = shapeProblem(raw)
  if (problem !== null) {
    return { status: 'rejected', reason: 'bad_shape', detail: problem }
  }
  const record = raw as Record<string, unknown>
  const fixes: ParseFix[] = []
  const incomeFactor = normalizeField('incomeFactor', record.incomeFactor as number, fixes)
  const billsPct = normalizeField('billsPct', record.billsPct as number, fixes)
  const oneOffMonths = normalizeField('oneOffMonths', record.oneOffMonths as number, fixes)
  const durationMonths = normalizeField('durationMonths', record.durationMonths as number, fixes)
  const summary = (record.summary as string).slice(0, SUMMARY_MAX_CHARS)
  const payload: ShockPayload = {
    intent: record.intent as ShockIntent,
    confidence: record.confidence as ShockConfidence,
    incomeFactor, billsPct, oneOffMonths, durationMonths, summary,
