combineWithTimeout:
```ts
interface CombinedAbort {
  signal: AbortSignal
  dispose: () => void
}

function combineWithTimeout(caller: AbortSignal | undefined, timeoutMs: number): CombinedAbort {
  const controller = new AbortController()
  const timeout = AbortSignal.timeout(timeoutMs)
  const onCallerAbort = () => controller.abort(caller?.reason)
  const onTimeoutAbort = () => controller.abort(timeout.reason)
  if (caller) {
    if (caller.aborted) controller.abort(caller.reason)
    else caller.addEventListener('abort', onCallerAbort, { once: true })
  }
  timeout.addEventListener('abort', onTimeoutAbort, { once: true })
  const dispose = () => {
    caller?.removeEventListener('abort', onCallerAbort)
    timeout.removeEventListener('abort', onTimeoutAbort)
  }
  return { signal: controller.signal, dispose }
}
```

Note: `AbortSignal.timeout` in TS lib ES2022/DOM — available in DOM lib (AbortSignal.timeout is in lib.dom since TS 4.8-ish). tsconfig lib includes DOM. Should be fine.

