import type { AccountProfile } from '../data/profiles'
import { applyTwist, scaleCents, type Twist } from './shocks'

/** The pinned model for the typed shock parse (docs/architecture.md). */
export const GEMINI_MODEL = 'gemini-3.5-flash-lite'

/** Hard cap for one parse request, matched to the 3 second UX budget. */
export const PARSE_TIMEOUT_MS = 3000/** What the model may map the sentence to. */
export type ShockIntent = 'job_loss' | 'bills_up' | 'one_off_cost' | 'mixed' | 'no_shock'

/** Model confidence in its own mapping. */
export type ShockConfidence = 'high' | 'medium' | 'low'

/** The four math and display fields of a mapped shock. */
export type SpecField = 'incomeFactor' | 'billsPct' | 'oneOffMonths' | 'durationMonths'

/** Auto correction kinds recorded while a payload is normalized. */
export type ParseFixKind = 'percent' | 'clamp' | 'round'

/** One auto correction: which field changed and which step changed it. */
export interface ParseFix {
  field: SpecField
  fix: ParseFixKind
}

/** Mapped shock parameters, normalized and in range (docs/architecture.md). */
export interface ShockSpec {
  /** Fraction of usual income kept, 0 to 1, two decimals. */
  incomeFactor: number
  /** Fractional rise in household bills, 0 to 1, two decimals. */
  billsPct: number
  /** One off cost in months of typical spending, 0 to 12, one decimal. */
  oneOffMonths: number
  /** Display only horizon in months, integer0 to 120. */
  durationMonths: number
}

/** The full model payload: spec fields plus the mapping metadata. */
export interface ShockPayload extends ShockSpec {
  intent: ShockIntent
  confidence: ShockConfidence
  summary: string
}

/** What leaves the browser in the prompt: baseline figures only. */
export interface PromptMetrics {
  accountId: string
  incomeCents: number
  fixedCostsCents: number
  spendingCents: number
  bufferCents: number
  householdBillsCents: number
  loanPaymentCents: number
  runwayMonths: number
}

/** Why a parse was rejected before any state change. */
export type RejectReason =
  | 'empty_input'
  | 'no_key'
  | 'malformed_json'
  | 'bad_shape'
  | 'no_shock'
  | 'low_confidence'
  | 'all_neutral'
  | 'rate_limited'
  | 'http_error'
  | 'network_error'
  | 'aborted'

/** A successful parse: the spec plus what the model said it mapped. */
export interface ParseOk {
  status: 'ok'
  spec: ShockSpec
  intent: ShockIntent
  confidence: 'high' | 'medium'
  summary: string
  fixes: ParseFix[]
}

/** A rejected parse: the reason the store turns into a fallback note. */
export interface ParseRejected {
  status: 'rejected'
  reason: RejectReason
  detail: string
}

/** A hard timeout or abort during the request (3 second budget). */
export interface ParseTimeout {
  status: 'timeout'
}

/** The parse result union: ok, rejected, or timeout. */
export type ParseOutcome = ParseOk | ParseRejected | ParseTimeout
```

