export const useConsole = create<ConsoleState>((set, get) => ({
  status: 'idle',
  error: null,
  bundle: null,
  query: '',
  selectedId: null,
  twist: IDLE_TWIST,
  activePresetId: null,
  typedStatus: 'idle',
  pendingShock: null,
  typedNote: null,
  shockMode: 'preset',

  boot: async () => {
    const status = get().status
    if (status === 'loading' || status === 'ready') {
      return
    }
    set({ status: 'loading', error: null })
    try {
      const bundle = await loadSharedProfiles()
      set({ status: 'ready', bundle, error: null })
    } catch (cause) {
      // The shared memo already cleared itself, so the next boot retries.
      set({ status: 'error', bundle: null, error: messageOf(cause) })
    }
  },

  setQuery: (query) => {
    set({ query })
  },

  selectAccount: (id) => {
    const bundle = get().bundle
    if (!bundle || !bundle.byId.has(id)) {
      return
    }
    retireTypedParse()
    set({
      selectedId: id,
      typedStatus: 'idle',
      pendingShock: null,
      typedNote: null,
      shockMode: 'preset',
    })
  },

  applyPreset: (id) => {
    const preset = presetById(id)
    if (!preset) {
      return
    }
    retireTypedParse()
    set({
      twist: normalizeTwist(preset.twist),
      activePresetId: preset.id,
      typedStatus: 'idle',
      pendingShock: null,
      typedNote: null,
      shockMode: 'preset',
    })
  },

  setTwistField: (patch) => {
    const twist = normalizeTwist({ ...get().twist, ...patch })
    set({ twist, activePresetId: matchPreset(twist) })
  },

  resetTwist: () => {
    retireTypedParse()
    set({
      twist: IDLE_TWIST,
      activePresetId: null,
      typedStatus: 'idle',
      pendingShock: null,
      typedNote: null,
      shockMode: 'preset',
    })
  },

  resetAll: () => {
    retireTypedParse()
    set({
      query: '',
      selectedId: null,
      twist: IDLE_TWIST,
      activePresetId: null,
      typedStatus: 'idle',
      pendingShock: null,
      typedNote: null,
      shockMode: 'preset',
    })
  },

  parseTypedShock: async (sentence) => {
    const generation = retireTypedParse()
    const { bundle, selectedId } = get()
    const profile = selectedId ? bundle?.byId.get(selectedId) : undefined
    if (!profile) {
      set({
        typedStatus: 'fallback',
        pendingShock: null,
        typedNote: NOTE_NO_ACCOUNT,
      })
      return
    }
    const controller = new AbortController()
    inFlightParse = controller
    set({ typedStatus: 'reading', pendingShock: null, typedNote: null })
    const outcome = await parseShockSentence(sentence, promptMetrics(profile), controller.signal)
    if (generation !== parseGeneration) {
      return
    }
    inFlightParse = null
    if (outcome.status === 'ok') {
      set({
        typedStatus: 'pending',
        pendingShock: {
          sentence,
          spec: outcome.spec,
          intent: outcome.intent,
          confidence: outcome.confidence,
          summary: outcome.summary,
          fixes: outcome.fixes,
        },
        typedNote: null,
      })
      return
    }
    set({
      typedStatus: 'fallback',
      pendingShock: null,
      typedNote: typedNoteFor(outcome),
    })
  },

  confirmTypedShock: () => {
    const pending = get().pendingShock
    if (!pending) {
      return
    }
    const twist = normalizeTwist(shockSpecToTwist(pending.spec))
    set({
      twist,
      activePresetId: matchPreset(twist),
      shockMode: 'gemini',
      typedStatus: 'idle',
      pendingShock: null,
      typedNote: null,
    })
  },

  adjustPendingShock: (field, delta) => {
    const pending = get().pendingShock
    if (!pending) {
      return
    }
    set({ pendingShock: { ...pending, spec: applySpecStep(pending.spec, field, delta) } })
  },

  cancelTypedShock: () => {
    retireTypedParse()
    set({ typedStatus: 'idle', pendingShock: null, typedNote: null })
  },
}))

